// src/components/feedbackForm.ts
function isNonEmptyString(value) {
  return typeof value === "string" && value.trim() !== "";
}
function parseFeedbackFormConfig(raw) {
  if (typeof raw === "string") {
    try {
      return parseFeedbackFormConfig(JSON.parse(raw));
    } catch {
      return null;
    }
  }
  if (typeof raw !== "object" || raw === null) return null;
  const { url, choiceEntry, choiceValue, queryEntry } = raw;
  if (!isNonEmptyString(url) || !isNonEmptyString(choiceEntry) || !isNonEmptyString(choiceValue) || !isNonEmptyString(queryEntry)) {
    return null;
  }
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:") return null;
  } catch {
    return null;
  }
  return { url, choiceEntry, choiceValue, queryEntry };
}

